head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > disabled]<br/>AutoComplete 컴포넌트의 비활성화(disabled) 상태를 설정합니다.",
    "validation" : [
        "true 설정 시, 컴포넌트를 비활성화(disabled) 상태로 설정합니다.",
        "true 설정 시, 최상위 태그에 'w2autoComplete_disabled' 클래스가 추가됩니다.",
        "false 설정 시, 컴포넌트의 비활성화(disabled) 상태를 해제합니다.",
        "미설정 시, 컴포넌트의 비활성화(disabled) 상태를 해제합니다.",
        "컴포넌트가 비활성화(disabled) 상태이면 클릭, 포커스, 입력, 아이템 선택 등과 같은 상호작용이 발생하지 않습니다.",
        "아이템 리스트창이 열린 상태에서 비활성화(disabled) 상태로 변경하면 아이템 리스트창이 닫힙니다.",
    ]
}



// stateInfo : 상태 확인 버튼을 누르는 시점의 리스트창 열림 여부, 표시 텍스트, 값
scwin.gVar = { "stateInfo" : "" };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (true)
    con_disabled.setValue("2");

    // 상태 확인 버튼 클릭 시 리스트창이 먼저 닫히므로 mousedown capture 단계에서 열림 여부와 값을 기록
    btn_getState.render.addEventListener("mousedown", scwin.captureState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof input_prev !== 'undefined') {
        input_prev.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 위 input_prev 는 Tab 출발점, 아래 target1 이 AutoComplete\n[절차]\n1. disabled 선택 -> Target 재생성 -> 출력 확인\n2. target1 입력창 클릭 / 글자 입력 / 화살표 버튼 클릭 / 리스트창의 아이템 클릭 / input_prev 클릭 후 Tab 키 -> 조작마다 상태 확인\n3. disabled 를 false 또는 미설정으로 재생성 -> 화살표 버튼으로 리스트창 열기 -> F2 키 (비활성화 상태로 변경, 다시 하려면 Target 재생성)\n[확인]\n- 결과창의 이벤트 발생 여부, 상태 확인의 리스트창 열림 여부 / 표시 텍스트 / 값\n- F2 키를 뗄 때 출력되는 변경 전 / 후 리스트창 열림 여부"', '', 'label1');

    // Tab 이동 출발점
    await $c.gcm.createBasicInput('', '', 'input_prev');

    // 미설정 옵션은 속성 자체를 넣지 않는다 (createCList 가 빈값 키 제외)
    let properties = {
        disabled : con_disabled.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onclick", "onfocus", "onviewchange"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicAutoComplete(cList, eList);

    // F2 키 처리 (재생성 때마다 새 target1 에 등록, 기존 target1 은 삭제되므로 중복 없음)
    target1.render.addEventListener("keyup", scwin.changeDisabledByKey, true);

    scwin.printCompState();
};



// validation 1 ~ 4 판정 출력 : 최상위 태그의 class, 입력 요소의 disabled 속성
scwin.printCompState = function () {
    let inputElem = document.querySelector("[id='" + target1.id + "_input']");
    let strDisabled = (con_disabled.getText() === "") ? "미설정" : con_disabled.getText();

    wf_body_bottom.getObj("scwin").setReturnValue("disabled " + strDisabled + " -> class : " + target1.render.className.trim() + " / 입력 요소 disabled 속성 : " + inputElem.hasAttribute("disabled"));
};



// 아이템 리스트창 열림 여부
scwin.isListOpen = function () {
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem) {
        return false;
    }
    let objStyle = getComputedStyle(itemTableElem);
    return objStyle.display !== "none" && objStyle.visibility !== "hidden";
};



// 버튼 mousedown 시점(리스트창이 닫히고 입력이 끝나기 전)의 리스트창 열림 여부, 표시 텍스트, 값 기록
//  - 표시 텍스트 : 입력 중이면 입력창의 글자, 아니면 선택된 아이템의 라벨
scwin.captureState = function (e) {
    let inputElem = document.querySelector("[id='" + target1.id + "_input']");
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    let strText = (inputElem.offsetWidth > 0) ? inputElem.value : labelElem.textContent;
    scwin.gVar.stateInfo = "리스트창 열림 : " + scwin.isListOpen() + " / 표시 텍스트 : " + strText + " / 값 : " + target1.getValue();
};



// 클릭 / 포커스 / 입력 / 아이템 선택 후 리스트창 열림 여부, 표시 텍스트, 값 출력 (validation 5)
scwin.btn_getState_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue(scwin.gVar.stateInfo);
};



// F2 키를 떼는 시점에 비활성화(disabled) 상태로 변경하고 변경 전 / 후 리스트창 열림 여부 출력 (validation 6)
//  - 마우스 클릭은 리스트창을 닫으므로 키 입력으로 변경
//  - 변경 전 값은 키 입력 처리가 끝난 뒤의 값이므로, true 이면 키 입력만으로는 닫히지 않은 것
scwin.changeDisabledByKey = function (e) {
    if (e.key !== "F2") {
        return;
    }
    let bBefore = scwin.isListOpen();
    target1.setDisabled(true);
    wf_body_bottom.getObj("scwin").setReturnValue("비활성화 변경 전 리스트창 열림 : " + bBefore + " -> 변경 후 리스트창 열림 : " + scwin.isListOpen());
};



// 테스트 샘플의 이벤트 처리 (validation 5)
scwin.target1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclick 이벤트 발생=====");
};



// 테스트 샘플의 이벤트 처리 (validation 5)
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus 이벤트 발생=====");
};



// 테스트 샘플의 이벤트 처리 (validation 5)
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
};
